// blinky_sys: clock domain sys @ 10000000 Hz, generated by Weft from the DAG (13 nodes)
module blinky_sys (
  input  wire clk,
  input  wire rst,
  output wire [0:0] o_pin_led_0
);
  reg [0:0] blink_led = 1'h0;
  reg [21:0] blink_every = 22'h0;
  wire [21:0] n2 = 22'h26259F;
  wire [0:0] n3;
  wire [0:0] n4 = 1'h1;
  wire [22:0] n5;
  wire [21:0] n6;
  wire [21:0] n7 = 22'h0;
  wire [21:0] n8;
  wire [0:0] blink_every_tick;  // probe
  wire [0:0] n10;
  wire [0:0] n11;
  assign n3 = blink_every == n2;  // .every("250ms") (line 11)
  assign n5 = {{1{1'b0}}, blink_every} + {{22{1'b0}}, n4};  // .every("250ms") (line 11)
  assign n6 = n5[21:0];  // .every("250ms") (line 11)
  assign n8 = (|n3) ? n7 : n6;  // .every("250ms") (line 11)
  assign blink_every_tick = n3;
  assign n10 = !(|blink_led);  // !$.led (line 11)
  assign n11 = (|blink_every_tick) ? n10 : blink_led;  // $.led = !$.led (line 11)
  assign o_pin_led_0 = blink_led;
  always @(posedge clk) begin
    blink_led <= rst ? 1'h0 : n11;
    blink_every <= rst ? 22'h0 : n8;
  end
endmodule

